std::vector<std::uint8_t> ReadB(const std::filesystem::path&p){std::ifstream s(p,std::ios::binary|std::ios::ate);if(!s)throw std::runtime_error("open "+p.string());auto n=s.tellg();std::vector<std::uint8_t>b(static_cast<std::size_t>(n));s.seekg(0);s.read((char*)b.data(),n);return b;}
std::string TokenName(int token){std::ostringstream s;s<<"default-token-"<<std::setfill('0')<<std::setw(6)<<token<<".bin";return s.str();}
id<MTLComputePipelineState> Pipeline(id<MTLDevice>d,const std::filesystem::path&p,const char*name){NSError*e=nil;id<MTLLibrary>l=[d newLibraryWithURL:[NSURL fileURLWithPath:[NSString stringWithUTF8String:p.string().c_str()]] error:&e];if(!l)throw std::runtime_error(e.localizedDescription.UTF8String);id<MTLFunction>f=[l newFunctionWithName:[NSString stringWithUTF8String:name]];if(!f)throw std::runtime_error(std::string("function ")+name);id<MTLComputePipelineState>q=[d newComputePipelineStateWithFunction:f error:&e];if(!q)throw std::runtime_error(e.localizedDescription.UTF8String);return q;}
void Dispatch(id<MTLCommandBuffer>cmd,id<MTLComputePipelineState>p,std::initializer_list<Binding>bindings,MTLSize threads,MTLSize group){id<MTLComputeCommandEncoder>e=[cmd computeCommandEncoder];[e setComputePipelineState:p];NSUInteger i=0;for(const auto&b:bindings)[e setBuffer:b.buffer offset:b.offset atIndex:i++];[e dispatchThreads:threads threadsPerThreadgroup:group];[e endEncoding];}
std::vector<std::uint8_t> Concat(std::initializer_list<std::pair<id<MTLBuffer>,std::size_t>>parts){std::vector<std::uint8_t>r;std::size_t n=0;for(auto&p:parts)n+=p.second;r.reserve(n);for(auto&p:parts){auto b=Payload(p.first,p.second);r.insert(r.end(),b.begin(),b.end());}return r;}
void Record(const std::filesystem::path&p,const std::string&id,std::uint8_t poison,const c::ExternalInputs&before,const c::ExternalInputs&after,const std::array<std::vector<std::uint8_t>,13>&w0,const std::array<std::vector<std::uint8_t>,13>&b0,const std::array<std::vector<std::uint8_t>,13>&w1,const std::array<std::vector<std::uint8_t>,13>&b1,const std::array<std::string,16>&checkpoints,const std::vector<std::uint8_t>&out,std::size_t mismatch,std::size_t canary,const std::string&dev){std::ofstream s(p);bool pass=mismatch==0&&canary==0;s<<"{\n  \"schema\": \"neuralstudio.fg.connected-custom-l56-l71-run.v1\",\n  \"backend\": \"mac-metal\",\n  \"run_id\": \""<<id<<"\",\n  \"process_id\": "<<getpid()<<",\n  \"poison_byte\": "<<unsigned(poison)<<",\n  \"launch_range\": [56, 71],\n  \"launch_count\": 16,\n  \"checkpoint_sha256\": {";for(int i=0;i<16;++i)s<<(i?", ":"\n    ")<<"\"launch-"<<std::setfill('0')<<std::setw(6)<<(56+i)<<"\": \""<<checkpoints[i]<<"\"";s<<"\n  },\n  \"external_input_generator\": \"splitmix64-fg-connected-custom-l56-l71-v1\",\n  \"external_input_pre_sha256\": [\""<<Sha256(before.a)<<"\", \""<<Sha256(before.b)<<"\", \""<<Sha256(before.c)<<"\"],\n  \"external_input_post_sha256\": [\""<<Sha256(after.a)<<"\", \""<<Sha256(after.b)<<"\", \""<<Sha256(after.c)<<"\"],\n  \"model_manifest_sha256\": \""<<c::kManifestSha256<<"\",\n  \"model_state\": [";for(std::size_t i=0;i<c::kModels.size();++i){auto&m=c::kModels[i];s<<(i?",":"")<<"{\"weight_token\":"<<m.weight_token<<",\"weight_sha256\":\""<<Sha256(w0[i])<<"\",\"bias_token\":"<<m.bias_token<<",\"bias_sha256\":\""<<Sha256(b0[i])<<"\"}";}s<<"],\n  \"model_state_post_sha256\": [";for(std::size_t i=0;i<c::kModels.size();++i)s<<(i?",":"")<<"[\""<<Sha256(w1[i])<<"\",\""<<Sha256(b1[i])<<"\"]";s<<"],\n  \"final_output_sha256\": \""<<Sha256(out)<<"\",\n  \"final_output_bytes\": "<<out.size()<<",\n  \"input_model_mismatched_bytes\": "<<mismatch<<",\n  \"canary_mismatched_bytes\": "<<canary<<",\n  \"in_process_handoff_count\": 15,\n  \"archived_intermediate_ingress\": false,\n  \"expected_output_file_opened\": false,\n  \"address_fields_recorded\": false,\n  \"device_name\": \""<<dev<<"\",\n  \"result\": \""<<(pass?"pass":"fail")<<"\"\n}\n";}
}

