Dispatch(cmd,upsample,{{l69a,G},{l70a,G},{up0b,Z}},MTLSizeMake(640,368,4),MTLSizeMake(8,4,1));Dispatch(cmd,upsample,{{l69b,G},{l70b,G},{up1b,Z}},MTLSizeMake(640,368,1),MTLSizeMake(8,4,1));Dispatch(cmd,upsample,{{l69c,G},{l70c,G},{up2b,Z}},MTLSizeMake(640,368,3),MTLSizeMake(8,4,1));
