std::array<std::string,16>ch={Sha256(Payload(l56,c::kL56Bytes)),Sha256(Payload(l57,c::kL57Bytes)),Sha256(Payload(l58,c::kL58Bytes)),Sha256(Payload(l59,c::kLow64Bytes)),Sha256(Payload(l60,c::kLow64Bytes)),Sha256(Payload(l61,c::kLow64Bytes)),Sha256(Payload(l62,c::kLow64Bytes)),Sha256(Payload(l63,c::kLow64Bytes)),Sha256(Payload(l64,c::kLow64Bytes)),Sha256(Payload(l65,c::kLow64Bytes)),Sha256(Payload(l66,c::kLow64Bytes)),Sha256(Payload(l67,c::kLow64Bytes)),Sha256(Concat({{l68a,c::kL68PlaneBytes},{l68b,c::kL68PlaneBytes},{l68c,c::kL68PlaneBytes}})),Sha256(Concat({{l69a,c::kL69Out0Bytes},{l69b,c::kL69Out1Bytes},{l69c,c::kL69Out2Bytes}})),Sha256(Concat({{l70a,c::kL70Out0Bytes},{l70b,c::kL70Out1Bytes},{l70c,c::kL70Out2Bytes}})),Sha256(Payload(l71,c::kL71Bytes))};
c::ExternalInputs ext1{Payload(a,c::kInputABytes),Payload(b,c::kInputBBytes),Payload(scalar,c::kInputCBytes)};std::array<std::vector<std::uint8_t>,13>w1,b1;std::size_t mismatch=Mismatches(ext0.a,ext1.a)+Mismatches(ext0.b,ext1.b)+Mismatches(ext0.c,ext1.c),canary=CanaryMismatches(a,c::kInputABytes)+CanaryMismatches(b,c::kInputBBytes)+CanaryMismatches(scalar,c::kInputCBytes);for(std::size_t i=0;i<13;++i){w1[i]=Payload(wb[i],c::kModels[i].weight_bytes);b1[i]=Payload(bb[i],c::kModels[i].bias_bytes);mismatch+=Mismatches(w0[i],w1[i])+Mismatches(b0[i],b1[i]);canary+=CanaryMismatches(wb[i],c::kModels[i].weight_bytes)+CanaryMismatches(bb[i],c::kModels[i].bias_bytes);}std::array<std::pair<id<MTLBuffer>,std::size_t>,22>buffers={{{l56,c::kL56Bytes},{l57,c::kL57Bytes},{l58,c::kL58Bytes},{l59,c::kLow64Bytes},{l60,c::kLow64Bytes},{l61,c::kLow64Bytes},{l62,c::kLow64Bytes},{l63,c::kLow64Bytes},{l64,c::kLow64Bytes},{l65,c::kLow64Bytes},{l66,c::kLow64Bytes},{l67,c::kLow64Bytes},{l68a,c::kL68PlaneBytes},{l68b,c::kL68PlaneBytes},{l68c,c::kL68PlaneBytes},{l69a,c::kL69Out0Bytes},{l69b,c::kL69Out1Bytes},{l69c,c::kL69Out2Bytes},{l70a,c::kL70Out0Bytes},{l70b,c::kL70Out1Bytes},{l70c,c::kL70Out2Bytes},{l71,c::kL71Bytes}}};for(auto&p:buffers)canary+=CanaryMismatches(p.first,p.second);auto out=Payload(l71,c::kL71Bytes);Write(dir/"checkpoint-l67.bin",Payload(l67,c::kLow64Bytes));Write(dir/"checkpoint-l68.bin",Concat({{l68a,c::kL68PlaneBytes},{l68b,c::kL68PlaneBytes},{l68c,c::kL68PlaneBytes}}));Record(dir/"run-receipt.json",v[4],poison,ext0,ext1,w0,b0,w1,b1,ch,out,mismatch,canary,d.name.UTF8String);Write(dir/"output.bin",out);bool pass=mismatch==0&&canary==0;std::cout<<"output_sha256="<<Sha256(out)<<"\nresult="<<(pass?"pass":"fail")<<'\n';return pass?0:3;}catch(const std::exception&e){std::cerr<<"error="<<e.what()<<'\n';return 1;}}}
